extra_methods.body:
_currentZoneName = newZoneName;
if (string.IsNullOrEmpty(newZoneName)) return;

// Load Audio Track
AudioDirectorAudioManager audioMgr = GameContext.Instance.Get<AudioDirectorAudioManager>();
if (audioMgr != null) {
    // Assuming a mapping exists or we play the zone name directly as cueId
    // For this example, we assume the track ID matches the zone name for simplicity in generated code
    // In a real project, you would map 'Neon Markets' to 'district_neon_markets_loop'
    string cueId = newZoneName.Replace(" ", "_").ToLower();
    audioMgr.Play(cueId);
}

// Load Sky Color
LightingDirector lightingDir = GameContext.Instance.Get<LightingDirector>();
if (lightingDir != null) {
    // Assuming a mapping exists or we use the zone name as a key for color data.
    // Since no specific color map is provided in the prompt, we will simulate a shift
    // based on the zone name length or just apply a generic 'night' tint if needed.
    // However, to strictly follow 'do what description says', we need a way to get the Color.
    // The prompt implies _skyColor field exists. Let's assume it gets set by an external event
    // or we initialize it here based on the zone name for demonstration.
    // Since we cannot define a massive map in extra_fields, we will assume the caller sets _skyColor
    // OR we use a simple heuristic if strictly needed. But the prompt says 'Switches... per zone transition'.
    // Let's assume there is an implicit mapping or the user expects us to handle the logic.
    // To make this compile and functional without external data, let's assume _skyColor is set externally
    // OR we use a default. But the field _skyColor is serialized.
    // Let's assume the caller sets _skyColor when switching zones.
    lightingDir.ApplyEnvironment();
}

// Cooldown reset
_zoneTransitionCooldown = 2f;

if (_target != null) {
	string targetTag = _target.tag;
	bool isHighThreat = (targetTag == "Enemy" || targetTag == "Boss");
	_isChaseMode = isHighThreat;
}

Vector3 spawnPos = transform.position;
if (_spawnPoint != null) {
    spawnPos = _spawnPoint.position;
}

float offsetAngle = Random.value * 2f * Mathf.PI;
float offsetDistance = Random.Range(0f, _spawnRadius);
return new Vector3(
    spawnPos.x + Mathf.Cos(offsetAngle) * offsetDistance,
    spawnPos.y + offsetDistance * 0.5f, // Slight height variation
    spawnPos.z + Mathf.Sin(offsetAngle) * offsetDistance
);

if (_ambientSource != null) {
    _ambientSource.Stop();
    string clipPath = "Audio/Ambient/" + zoneName + "_Theme";
    AudioClip clip = Resources.Load<AudioClip>(clipPath);
    if (clip != null) {
        _ambientSource.clip = clip;
        _ambientSource.Play();
    }
}

if (_pool.Count > 0) {
    AudioSource source = _pool[0];
    _pool.RemoveAt(0);
    string clipPath = "Audio/SFX/" + cueId;
    AudioClip clip = Resources.Load<AudioClip>(clipPath);
    if (clip != null) {
        source.PlayOneShot(clip, worldPos);
    }
}

if (Application.isEditor) return; // Only apply in build or via specific post-process component if available
// Note: Direct URP scriptable render feature manipulation requires a reference to the ScriptableRendererFeature.
// Since no such field exists in the baseline, this method acts as a placeholder for logic that would
// ideally be handled by a PostProcessVolume or similar system injected elsewhere.
// For this specific subsystem constraint, we assume the fadeCanvas handles visual transition,
// and audio is managed separately.

_rainAudioSource = null; // Reset
if (zoneName == "slums")
{
    _rainAudioSource = FindObjectOfType<AudioSource>();
    if (_rainAudioSource != null)
        _rainAudioSource.Play();
}
else
{
    if (_rainAudioSource != null)
        _rainAudioSource.Stop();
}

_bossProgrammerEnemy = GetComponentInParent<MonoBehaviour>();
if (_bossProgrammerEnemy != null) {
    var agent = _bossProgrammerEnemy.GetComponent<NavMeshAgent>();
    if (agent == null) agent = _bossProgrammerEnemy.GetComponentInChildren<NavMeshAgent>();
    if (agent != null) {
        agent.enabled = false;
    }
}
if (_isBossDefeated) {
    OnMissionComplete?.Invoke();
}

_currentStepIndex++;
if (_currentStepIndex < steps.Count) {
    CurrentStep = steps[_currentStepIndex];
}
else {
    Finished = true;
}

string currentObjectiveId = _currentStepIndex >= 0 ? steps[_currentStepIndex].objective_id : null;
if (zoneName == "Market District" && currentObjectiveId == "obj_1") {
    AdvanceStep();
}
else if (zoneName == "Corporate Tower" && currentObjectiveId == "obj_3") {
    AdvanceStep();
}
